// Domain-neutral row shaping. Three defects found by testing are fixed here:
//  (1) The first version DROPPED every non-due row, so the FALSE output of the
//      If node could never fire. Every row now leaves this node with an
//      explicit needs_action boolean, so both outputs are reachable.
//  (2) Duplicate record_id values produced duplicate outbound messages.
//      A stable row key de-duplicates the input before anything is sent.
//  (3) A retry after a successful write-back re-sent the same message.
//      Terminal statuses are skipped, and the write-back sets a terminal
//      status, so the second run is a no-op.
const cfg = $('CONFIG').first().json;
const threshold = Number(cfg.due_days || 3);
const terminal = new Set(['done', 'contacted', 'sent', 'complete', 'completed', 'paid']);
const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const p = item.json;
  const key = String(p.record_id !== undefined && p.record_id !== null
    ? p.record_id
    : String(p.email) + '|' + String(p.item_ref));
  if (seen.has(key)) continue;
  seen.add(key);

  const status = String(p.status || '').toLowerCase();
  const stamp = new Date(String(p.last_activity) + 'T00:00:00Z').getTime();
  const days = Number.isFinite(stamp)
    ? Math.max(0, Math.floor((Date.now() - stamp) / 86400000))
    : 0;

  output.push({
    json: Object.assign({}, p, {
      days_since: days,
      needs_action: !terminal.has(status) && days >= threshold
    })
  });
}

return output;

// Collapse due rows into one item per email address.
// Keying on the address (not the name) is deliberate: the address is the
// delivery channel, so two spellings of the same client still get one email.
const order = [];
const groups = new Map();

for (const item of $input.all()) {
  const p = item.json;
  const email = String(p.email || '').trim().toLowerCase();
  // No address means no email. The row is left untouched in the sheet so it
  // stays visible instead of being silently marked as handled.
  if (!email) continue;

  let g = groups.get(email);
  if (!g) {
    g = { email: email, name: String(p.contact_name || '').trim(), rows: [], max_days: 0 };
    groups.set(email, g);
    order.push(email);
  }
  if (!g.name && p.contact_name) g.name = String(p.contact_name).trim();

  g.rows.push({
    record_id: p.record_id,
    row_number: p.row_number,
    item_ref: p.item_ref,
    days_since: Number(p.days_since) || 0
  });
  g.max_days = Math.max(g.max_days, Number(p.days_since) || 0);
}

return order.map(function (k) {
  const g = groups.get(k);
  return {
    json: {
      recipient: g.email,
      contact_name: g.name,
      invoice_count: g.rows.length,
      max_days: g.max_days,
      rows: g.rows
    }
  };
});

// One message per contact, built from the grouped item.
// A single invoice keeps its own reference in the subject; a batch is described
// as "3 invoices". The list itself is always spelled out in the body, so the
// client can see every invoice in one place.
const cfg = $('CONFIG').first().json;
const subjTpl = String(cfg.subject_template || '');
const bodyTpl = String(cfg.message_template || '');
const listTpl = String(cfg.invoice_list_template || '- {{item}} ({{days}} days overdue)');

const fill = function (s, v) {
  return String(s).replace(/\{\{([a-z_]+)\}\}/g, function (m, k) {
    return v[k] !== undefined && v[k] !== null ? String(v[k]) : m;
  });
};

return $input.all().map(function (item) {
  const g = item.json;
  const rows = g.rows || [];
  const count = rows.length;
  const list = rows
    .map(function (r) { return fill(listTpl, { item: r.item_ref, days: r.days_since }); })
    .filter(function (line) { return String(line).trim() !== ''; })
    .join('\n');

  const vars = {
    name: g.contact_name || 'there',
    item: count === 1 ? String(rows[0].item_ref) : count + ' invoices',
    days: String(g.max_days),
    count: String(count),
    invoice_list: list
  };

  return {
    json: Object.assign({}, g, {
      recipient: g.recipient,
      subject: fill(subjTpl, vars),
      message: fill(bodyTpl, vars)
    })
  };
});
